def write(name,obj): (OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')

def sample_pdf():
 path=SAMPLE/'rn5-001-solar-quote-decoder-representative-sample.pdf'; c=Canvas(str(path),pagesize=letter); W,H=letter
 navy=HexColor('#17324D'); gold=HexColor('#E8A23A'); pale=HexColor('#F3F6F7'); gray=HexColor('#53616C')
 def head(k,title,sub=''):
  c.setFillColor(navy);c.rect(0,H-54,W,54,fill=1,stroke=0);c.setFillColor(white);c.setFont('Helvetica-Bold',10);c.drawString(42,H-22,k);c.setFont('Helvetica-Bold',20);c.drawString(42,H-44,title)
  if sub:c.setFillColor(gray);c.setFont('Helvetica',10);c.drawString(42,H-70,sub)
 def box(y,h,title,lines):
  c.setFillColor(pale);c.roundRect(42,y-h,W-84,h,7,fill=1,stroke=0);c.setFillColor(navy);c.setFont('Helvetica-Bold',12);c.drawString(55,y-20,title);c.setFont('Helvetica',10.5)
  for j,line in enumerate(lines):c.drawString(55,y-42-j*18,line)
  rule_y=y-55-len(lines)*18
  c.setStrokeColor(HexColor('#C8D1D7'));c.setLineWidth(.6)
  while rule_y>y-h+18:
   c.line(55,rule_y,W-55,rule_y);rule_y-=26
 pages=[
 ('1 / ORIENT','Compare the deal, not the pitch','A decision workbook for real rooftop-solar and battery proposals',[('The job',['Bring 2–4 written proposals. Record facts; mark assumptions; turn gaps into questions.']),('Decision path',['1 Normalize cash price  2 Separate financing  3 Compare production  4 Audit scope','5 Compare equipment  6 Compare warranties  7 Resolve gaps  8 Decide or pause'])]),
 ('2 / NORMALIZE','Quote intake: proposal A','Copy what the proposal says. Do not improve missing information.',[('Price',['Cash price: __________   Financed principal: __________   Dealer fee disclosed? YES / NO / UNCLEAR','System size (kW DC): ______   Cash cost per watt: ______']),('Production assumptions',['Annual production estimate: ______ kWh   Utility escalation assumption: ______%','Shading/site model named? __________   Performance guarantee? __________']),('Evidence status',['For each number mark: WRITTEN IN QUOTE / SALES CLAIM / CALCULATED / MISSING'])]),
 ('3 / COMPARE','Three-proposal normalization','One row, one comparable fact. “Included” is not a specification.',[('Core economics',['A cash $_____  $/W_____     B cash $_____  $/W_____     C cash $_____  $/W_____','Loan principal A_____ B_____ C_____   Total scheduled payments A_____ B_____ C_____']),('System',['DC size A_____ B_____ C_____   first-year production A_____ B_____ C_____']),('Gap question',['Which proposal looks cheapest only because one scope item or finance cost is hidden? __________'])]),
 ('4 / FINANCE','Cash price and loan are separate decisions','A low APR does not prove a low total cost.',[('Normalize',['Cash price: ______   Loan principal: ______   Difference: ______   Term: ______','Monthly payment before any re-amortization: ______   after: ______']),('Ask in writing',['Is a dealer fee embedded? Can I use outside financing? Is there a prepayment penalty?','What happens if I sell the house before payoff?']),('Boundary',['This workbook compares disclosed terms. It does not recommend a loan or replace legal advice.'])]),
 ('5 / ASSUMPTIONS','Production is an estimate','Compare the inputs beneath the headline savings.',[('Trace the estimate',['Usage baseline: ______   Roof orientation: ______   Shade assumption: ______','Panel degradation: ______   Utility-rate escalation: ______   Export-credit assumption: ______']),('Stress test',['If export credit or escalation is lower, does the proposal still meet your objective? YES / NO / UNKNOWN']),('Question',['Which assumption creates the largest difference between proposals? __________'])]),
 ('6 / SCOPE','What is actually included?','Turn “turnkey” into a written scope.',[('Included / excluded',['Panel or roof work ______  Main-panel work ______  Permits ______  Interconnection ______','Monitoring ______  Critter guard ______  Trenching ______  Battery backup circuits ______']),('Handoff',['Who owns each permit, inspection, utility submission and correction? __________']),('Stop sign',['A material scope item is verbal only: PAUSE / GET WRITTEN CONFIRMATION'])]),
 ('7 / WARRANTY','Map promises to responsible parties','A 25-year headline can hide several different warranties.',[('Separate',['Panel product ______  performance ______  inverter ______  battery ______','Installer workmanship ______  roof penetration ______  labor/shipping exclusions ______']),('Failure path',['Who receives the claim? ______  Who pays diagnosis? ______  What if installer closes? ______']),('Compare',['Which warranty difference is real after exclusions and responsible-party risk? __________'])]),
 ('8 / DECIDE','Sign, question, or pause','A decision is allowed to remain unresolved.',[('Unresolved material items',['1 __________________________  owner ______ due ______','2 __________________________  owner ______ due ______','3 __________________________  owner ______ due ______']),('Decision',['SIGN A / SIGN B / SIGN C / REQUEST REVISED QUOTES / PAUSE']),('Reason in one sentence',['We chose or paused because ________________________________________________'])])]
 for k,t,s,blocks in pages:
  head(k,t,s);y=H-96
  block_h=205 if len(blocks)==2 else 145
  for title,lines in blocks:
   box(y,block_h,title,lines);y-=block_h+16
  c.setFillColor(gray);c.setFont('Helvetica',8);c.drawString(42,25,'Representative product only — not a full manuscript. Independent; no installer or government affiliation.');c.showPage()
 c.save();return path

def main():
 rows=broad();deep=deep_rows(rows);top=[next(x for x in deep if x['id']==oid) for oid in TOP_IDS]
 write('broad-opportunities.json',{'schema_version':'radar-native-5-broad/v1','run_id':'RN5','observed_at':DATE,'count':len(rows),'opportunities':rows})
